const std = @import("std");

pub fn main() !void {
    const text = "Hello, Zig World!";
    var count: u32 = 0;

    for (text) |ch| {
        switch (ch) {
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U' => count += 1,
            else => {},
        }
    }

    std.debug.print("Vowels: {}\n", .{count});
}

